class string_buf { public: int pad0; int pad4; int char_length; };
class stringx {
  friend stringx operator+(const stringx&, const stringx&);
public: char* chars; string_buf* my_buf;
public:
  stringx(); stringx(const stringx&); stringx(const char*, int = -1); ~stringx();
  stringx& operator=(const stringx&);
  void append(const char*, int); void append(const stringx&); void make_room(int);
};
inline stringx operator+(const stringx& lhs, const stringx& rhs) {
  stringx foo; foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs); foo.append(rhs); return foo;
}
inline stringx operator+(const char* lhs, const stringx& rhs) {
  stringx foo; int n = __builtin_strlen(lhs); foo.make_room(n + rhs.my_buf->char_length);
  foo.append(lhs, n); foo.append(rhs); return foo;
}

